namespace App\Http\Controllers\Fleet;

use App\Http\Controllers\Controller;
use App\Models\GpsDevice;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;

class FleetTelemetryController extends Controller
{
    public function telemetry(Request $request, string $hardwareSerial): JsonResponse
    {
        $device = $request->user()->organization
            ->gpsDevices()
            ->where('hardware_serial', $hardwareSerial)
            ->firstOrFail();

        $telemetry = $device->telemetryPoints()
            ->latest('recorded_at')
            ->limit(50)
            ->get(['latitude', 'longitude', 'speed', 'recorded_at']);

        return response()->json(['device' => $hardwareSerial, 'history' => $telemetry]);
    }
}
